"""Real Edge additions; no APIClient and no live user database."""
import csv,io,json
from playwright.sync_api import expect

def exercise(browser,page,context,origin,out,password,login,api,check,report):
    extra=[]
    try:
        first=browser.new_context(viewport={'width':1440,'height':1000});second=browser.new_context(viewport={'width':1440,'height':1000});third=browser.new_context(viewport={'width':1440,'height':1000});extra.extend([first,second,third]);a=first.new_page();b=second.new_page();c=third.new_page()
        for p in [a,b,c]:p.on('pageerror',lambda e:report['page_errors'].append(str(e)))
        for p in [a,b,c]:login(p,'e2e-user')
        a.goto(origin+'/settings');expect(a.get_by_role('heading',name='账户安全中心')).to_be_visible();expect(a.get_by_text('当前会话',exact=True)).to_have_count(1);check('Edge security sessions current safe display')
        rows=api(a,'/auth/sessions/')['body']['data'];target=next(x['id'] for x in api(b,'/auth/sessions/')['body']['data'] if x['current']);row=a.locator('tr').filter(has_text=target);row.get_by_role('button',name='退出会话',exact=True).click();a.locator('.arco-popconfirm-popup-content:visible').get_by_role('button',name='确定',exact=True).click();expect(a.locator('tr').filter(has_text=target)).to_have_count(0)
        results=[api(p,'/auth/user-info/')['status'] for p in [b,c]];check('Edge single session revoke preserves current and other',sorted(results)==[200,403] and api(a,'/auth/user-info/')['status']==200)
        a.get_by_role('button',name='退出其他会话',exact=True).click();a.locator('.arco-popconfirm-popup-content:visible').get_by_role('button',name='确定',exact=True).click();expect(a.get_by_text('其他会话',exact=True)).to_have_count(0);check('Edge exit others retains current old contexts denied',all(api(p,'/auth/user-info/')['status']==403 for p in [b,c]) and api(a,'/auth/user-info/')['status']==200)
        a.route('**/api/auth/sessions/',lambda route:route.fulfill(status=503,content_type='application/json',body=json.dumps({'error':{'code':'UNAVAILABLE','message':'Synthetic session retry'}})));a.get_by_role('button',name='刷新会话',exact=True).click();expect(a.get_by_text('Synthetic session retry',exact=False)).to_be_visible();a.unroute('**/api/auth/sessions/');a.get_by_role('button',name='重试会话',exact=True).click();expect(a.get_by_text('Synthetic session retry',exact=False)).to_have_count(0);check('Edge session failure retry works')
        a.set_viewport_size({'width':390,'height':844});check('Edge security center narrow no document overflow',a.evaluate('document.documentElement.scrollWidth<=innerWidth'));a.screenshot(path=str(out/'security-390.png'),full_page=True)
        login(page,'e2e-root');page.goto(origin+'/system/audit');page.get_by_placeholder('动作，如 user.create').fill('session.login');uid=api(page,'/auth/user-info/')['body']['data']['id'];page.get_by_placeholder('主体ID（正整数）').fill(str(uid));page.get_by_placeholder('开始，如 2026-11-20T00:00:00+08:00').fill('2026-02-30T00:00:00+08:00');page.get_by_role('button',name='查询',exact=True).click();expect(page.locator('.arco-alert-error')).to_be_visible();check('Edge invalid audit calendar visible 400 error')
        page.get_by_placeholder('开始，如 2026-11-20T00:00:00+08:00').fill('2026-01-01T00:00:00+08:00');page.get_by_role('button',name='重试',exact=True).click();expect(page.locator('.arco-alert-error')).to_have_count(0);expect(page.locator('tbody tr').first).to_contain_text('session.login');check('Edge actor and timezone filters recover correctly')
        with page.expect_download() as event:page.get_by_role('button',name='导出安全CSV',exact=True).click()
        download=event.value;destination=out/'download-safe-audit.csv';download.save_as(destination);content=destination.read_bytes();data=list(csv.DictReader(io.StringIO(content.decode('utf-8-sig'))));check('Edge actual CSV download BOM shared filters',content.startswith(b'\xef\xbb\xbf') and data and all(row['action']=='session.login' and row['actor_id']==str(uid) for row in data));check('Edge CSV safe header excludes secrets',set(data[0])=={'id','actor_id','actor_name','action','resource','object_id','outcome','created_at'} and password not in content.decode('utf-8-sig'))
        page.route('**/api/audit/export/?*',lambda route:route.fulfill(status=503,content_type='application/json',body=json.dumps({'error':{'code':'UNAVAILABLE','message':'Synthetic export retry'}})));page.get_by_role('button',name='导出安全CSV',exact=True).click();expect(page.get_by_text('Synthetic export retry',exact=False)).to_be_visible();page.unroute('**/api/audit/export/?*')
        with page.expect_download():page.get_by_role('button',name='重试导出',exact=True).click()
        expect(page.get_by_text('Synthetic export retry',exact=False)).to_have_count(0);check('Edge export failure retry no false success')
        page.goto(origin+'/system/users');search=page.get_by_placeholder('搜索用户名 / 邮箱');search.fill('e2e-user');search.press('Enter');row=page.locator('tr').filter(has_text='e2e-user@example.invalid');expect(row).to_have_count(1);row.get_by_role('button',name='撤销全部会话',exact=True).click();popup=page.locator('.arco-popconfirm-popup-content:visible');expect(popup).to_contain_text('包括其当前会话');popup.get_by_role('button',name='确定',exact=True).click();expect(page.get_by_text('该用户全部会话已撤销',exact=True)).to_be_visible();check('Edge root revokes target existing session',api(a,'/auth/user-info/')['status']==403)
        search.fill('e2e-root');search.press('Enter');row=page.locator('tr').filter(has_text='e2e-root@example.invalid');expect(row).to_have_count(1);row.get_by_role('button',name='撤销全部会话',exact=True).click();popup=page.locator('.arco-popconfirm-popup-content:visible');expect(popup).to_contain_text('若是本人');popup.get_by_role('button',name='确定',exact=True).click();page.wait_for_url('**/login');check('Edge root self revoke confirmed returns login',api(page,'/auth/user-info/')['status']==403)
        login(page,'e2e-boss');page.goto(origin+'/system/users');expect(page.get_by_role('button',name='新建用户',exact=True)).to_be_visible();check('Edge BOSS cannot see root session revoke',page.get_by_role('button',name='撤销全部会话',exact=True).count()==0)
    finally:
        for item in extra:item.close()
